# Check if there's a pattern: do agents READ the file before the failed edit?
# Analyze the last 20 sessions with edit failures
python3 << 'EOF'
import json, re, os, glob

results = {"read_before": 0, "no_read_before": 0, "total_failures": 0}
sessions = sorted(os.listdir(".state/sessions/history/"), reverse=True)[:40]

for s in sessions:
    sf = f".state/sessions/history/{s}/session.jsonl"
    if not os.path.exists(sf):
        continue

    lines = []
    with open(sf) as f:
        for line in f:
            try:
                lines.append(json.loads(line))
            except:
                pass

    for i, msg in enumerate(lines):
        content = json.dumps(msg.get('content', ''))
        if msg.get('role') == 'toolResult' and ('Could not find the exact text' in content):
            results["total_failures"] += 1

            # Find the edit call (look backward)
            edit_path = None
            for j in range(i-1, max(i-5, 0), -1):
                prev = json.dumps(lines[j].get('content', ''))
                path_match = re.search(r'"path":\s*"([^"]+)"', prev)
                if path_match and ('edit' in prev.lower()):
                    edit_path = path_match.group(1)
                    break

            if not edit_path:
                continue

            # Was there a read() of the same file BEFORE this edit in the same session?
            had_read = False
            for j in range(0, i):
                prev = json.dumps(lines[j].get('content', ''))
                if 'read' in prev.lower() and edit_path in prev:
                    had_read = True
                    break

            if had_read:
                results["read_before"] += 1
            else:
                results["no_read_before"] += 1

print(f"Total edit-match failures analyzed: {results['total_failures']}")
print(f"Had read() before failed edit: {results['read_before']} ({100*results['read_before']/max(1,results['total_failures']):.0f}%)")
print(f"NO read() before failed edit: {results['no_read_before']} ({100*results['no_read_before']/max(1,results['total_failures']):.0f}%)")
print(f"(Path not found in analysis: {results['total_failures'] - results['read_before'] - results['no_read_before']})")
EOF

# Look at scope creep patterns - sessions where the agent started one task but expanded
# Focus on longer sessions (high turn count) and check if task stays focused
python3 << 'EOF'
import json, os

sessions = sorted(os.listdir(".state/sessions/history/"), reverse=True)[:30]

for s in sessions:
    meta_path = f".state/sessions/history/{s}/meta.json"
    sf = f".state/sessions/history/{s}/session.jsonl"
    if not os.path.exists(meta_path) or not os.path.exists(sf):
        continue

    try:
        meta = json.load(open(meta_path))
    except:
        continue

    agent = meta.get('agent', '?')

    # Count tool calls
    tool_calls = 0
    with open(sf) as f:
        for line in f:
            try:
                msg = json.loads(line)
                if msg.get('role') == 'toolResult':
                    tool_calls += 1
            except:
                pass

    status = meta.get('status', '?')

    # Only show sessions with many tool calls (potential scope creep)
    if tool_calls > 20:
        print(f"{s} ({agent}): {tool_calls} tool calls, status={status}")

