# Analyze the 65-tool-call optimizer session - what was it doing?
python3 << 'EOF'
import json

sf = ".state/sessions/history/s_1774138325283_357/session.jsonl"
lines = []
with open(sf) as f:
    for line in f:
        try:
            lines.append(json.loads(line))
        except:
            pass

# Get the task/first message
for msg in lines[:3]:
    if msg.get('role') == 'user':
        content = msg.get('content', '')
        if isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'text':
                    text = c.get('text', '')[:500]
                    print(f"TASK: {text}")
                    break
        elif isinstance(content, str):
            print(f"TASK: {content[:500]}")
        break

# Count tool types
tool_types = {}
for msg in lines:
    content_str = json.dumps(msg.get('content', ''))
    if msg.get('role') == 'assistant':
        for tool in ['read', 'edit', 'write', 'bash', 'agents', 'finish', 'checkpoint']:
            if f'"toolName":"{tool}"' in content_str or f'"name":"{tool}"' in content_str or f'"toolName": "{tool}"' in content_str:
                tool_types[tool] = tool_types.get(tool, 0) + 1

print(f"\nTool breakdown:")
for t, c in sorted(tool_types.items(), key=lambda x: -x[1]):
    print(f"  {t}: {c}")

# Get finish status
for msg in reversed(lines):
    content_str = json.dumps(msg.get('content', ''))
    if 'finish' in content_str and ('success' in content_str or 'partial' in content_str or 'failure' in content_str):
        # Find the status
        import re
        status_match = re.search(r'"status":\s*"(\w+)"', content_str)
        summary_match = re.search(r'"summary":\s*"([^"]{0,300})"', content_str)
        if status_match:
            print(f"\nFinish status: {status_match.group(1)}")
        if summary_match:
            print(f"Summary: {summary_match.group(1)}")
        break
EOF
